draw.dashboard=()=>{const student=role==='Student',teacher=role==='Teaching staff';const name=db.profile.name.split(' ')[0];const title=student?(lang==='ar'?`أهلًا بعودتك، ${esc(name)}`:`Welcome back, ${esc(name)}`):tr(info.dashboard[0]);return vhead(title,'Your university, in one place.',`<span class="badge">${tr('Local demo')} · 2026/27</span>`)+`<div class="grid"><div><section class="hero"><div class="eyebrow">UNIFLOW / ${tr(role).toUpperCase()}</div><h2>${tr('Your next steps')}</h2><p>${tr('Choose what you want to do next.')}</p>${student?'':`<button data-page="${teacher?'grading':role==='Administrator'?'support':'incidents'}">${tr(teacher?'Review':'Open')} ↗</button>`}<div class="orbit"><span class="planet"></span></div></section><div class="quickactions">${shortcuts[role].map(p=>quick(p)).join('')}</div><div class="stats">${student?stat('3.68',tr('Current GPA'),icon('chart'))+stat('94%',tr('Attendance'),icon('users'))+stat(courses.length,tr('My courses'),icon('book'))+stat(state.tasks.filter(t=>!t.done&&!t.submitted).length,tr('Upcoming tasks'),icon('check')):teacher?stat(courses.length,tr('My courses'),icon('book'))+stat(db.grades.filter(g=>g.status!=='Published').length,tr('Needs review'),icon('check'))+stat(db.materials.length,tr('Materials'),icon('file'))+stat(db.assessments.length,tr('Quizzes & exams'),icon('calendar')):role==='Administrator'?stat(db.users.length,tr('Users & roles'),icon('users'))+stat(db.offerings.length,tr('Courses & sections'),icon('book'))+stat(db.tickets.filter(t=>t.status!=='Resolved').length,tr('Open'),icon('help'))+stat(db.enrolments.filter(e=>e.status==='Pending').length,tr('Pending'),icon('clock')):stat('7',tr('Service health'),icon('server'))+stat(db.incidents.filter(x=>x.status!=='Resolved').length,tr('Incidents & alerts'),icon('bell'))+stat('4.8s','AI p95 · sample',icon('clock'))+stat('$12.40','AI cost · sample',icon('chart'))}</div><div class="sectionhead"><h2>${tr(student||teacher?'My courses':'Your next steps')}</h2><button data-page="${student||teacher?'courses':'more'}">${tr('View all')} ↗</button></div>${student||teacher?`<div class="courses">${courses.slice(0,3).map(courseCard).join('')}</div>`:`<div class="directory">${allowed[role].filter(x=>['users','departments','timetable','enrolments','incidents','storage','security','audit'].includes(x)).slice(0,4).map(p=>quick(p)).join('')}</div>`}</div><div class="rightcol"><section class="panel"><div class="sectionhead"><h2>${tr(student?'Today’s schedule':'Needs review')}</h2><button data-page="${student?'schedule':teacher?'grading':role==='Administrator'?'support':'incidents'}">${tr('View all')} ↗</button></div>${student?`<div class="timeline"><div class="event"><div class="time">09:00<br>10:15</div><div class="eventbody"><b>Data Structures</b><small>Engineering Hall 101</small><button class="textbutton" data-building="Engineering">${tr('Campus map')} ↗</button></div></div><div class="event"><div class="time">13:30<br>14:45</div><div class="eventbody"><b>Database Systems</b><small>Engineering Hall 315</small></div></div></div>`:`<p class="explain">${tr('Local records only')}</p><button class="primary" data-page="${teacher?'grading':role==='Administrator'?'support':'incidents'}">${tr('Review')} →</button>`}</section><section class="panel assistantcard"><div class="spark">${icon('spark')}</div><h2>${tr('AI assistant')}</h2><p>${lang==='ar'?'اسأل عن المقررات والمواعيد في البيانات التجريبية.':'Find a deadline, explore a course concept, or review a sample policy.'}</p><button data-page="assistant">${tr('Continue')} ↗</button><small style="margin-top:12px">${lang==='ar'?'إجابات تجريبية — غير متصل بنموذج ذكاء اصطناعي':'Sample answers · no AI model connected'}</small></section><section class="panel"><h2>${tr('Announcements')}</h2>${visibleAnnouncements().slice(0,2).map(n=>`<div class="healthrow"><div><b>${esc(n.title)}</b><small>${esc(n.effective)} · v${n.version}</small></div></div>`).join('')}<button class="textbutton" data-page="announcements">${tr('View all')} ↗</button></section></div></div>`};
courseCard=c=>`<button class="course" data-open-course="${c.id}"><div class="cover ${c.color}"><span class="code">${c.id} · A</span><span class="graphic">${c.symbol}</span></div><div class="coursebody"><h3>${esc(c.name)}</h3><small>${esc(c.teacher)}</small><div class="progresslabel"><span>${tr('Grades')} ${c.grade}%</span><span>${tr('Attendance')} ${c.attendance}%</span></div><div class="progress"><span style="width:${c.progress}%"></span></div><div class="coursefooter">${tr('View course')} →</div></div></button>`;
draw.courses=()=>vhead('My courses','All your course work in one place.')+`<div class="toolbar"><input id="courseSearch" placeholder="${tr('Search records…')}" aria-label="Search courses" value="${esc(listQuery)}"></div><div class="courses" id="courseResults">${courses.filter(c=>(c.name+c.id).toLowerCase().includes(listQuery.toLowerCase())).map(courseCard).join('')}</div>`;
draw.more=()=>vhead('All services','Browse all services')+`<div class="directory">${allowed[role].filter(p=>!['dashboard','course','attempt','more','search'].includes(p)).map(p=>`<button data-page="${p}">${icon(info[p][1])}<div><b>${tr(info[p][0])}</b></div></button>`).join('')}</div>`;
const courseTabs=['Overview','Materials','Assignments','Quizzes & exams','Grades','Attendance','Announcements','Discussion'];draw.course=()=>{const c=courses.find(c=>c.id===selectedCourse)||courses[0];return vhead(c.name,`${c.id} · ${c.teacher} · Section A`)+`<div class="tabs" role="tablist">${courseTabs.map(t=>`<button role="tab" aria-selected="${courseTab===t}" data-course-tab="${t}" class="${courseTab===t?'active':''}">${tr(t)}</button>`).join('')}</div>${courseTab==='Overview'?`<div class="twocol"><section class="panel"><h2>${tr('Overview')}</h2><p>${c.topic}</p><div class="stats" style="grid-template-columns:1fr 1fr">${stat(c.grade+'%',tr('Grades'),'')}${stat(c.attendance+'%',tr('Attendance'),'')}</div><h3>${tr('Your next steps')}</h3>${state.tasks.filter(t=>t.course===c.name).map(t=>`<div class="healthrow"><div><b>${esc(t.title)}</b><small>${esc(t.due)}</small></div><button class="textbutton" data-page="assignments">${tr('Open')} →</button></div>`).join('')}<button class="primary" data-course-tab="Materials">${tr('Materials')} →</button></section><section class="panel assistantcard"><h2>${tr('AI assistant')}</h2><p>Explore ${esc(c.topic.toLowerCase())}.</p><button data-context="${c.id}">${tr('Continue')} →</button></section></div>`:courseTab==='Materials'?materialsView(c.id):courseTab==='Assignments'?assignmentsView(c.id):courseTab==='Quizzes & exams'?quizList(c.id):courseTab==='Grades'?`<section class="panel"><h2>${tr('Grades')}</h2><p>Coursework: ${c.grade}% · Attendance: ${c.attendance}%</p>${db.grades.filter(g=>g.course===c.id&&g.status==='Published').map(g=>`<div class="healthrow"><b>${esc(g.assessment)}</b><span>${g.score}%</span></div>`).join('')}<button class="secondary" data-review-grade="${c.id}">${tr('Request correction')}</button></section>`:courseTab==='Attendance'?attendanceView(c.id):courseTab==='Announcements'?announcementsView(c.id):messagesView(c.id)}`};
const courseOpts=()=>courses.map(c=>[c.id,`${c.id} · ${c.name}`]);const field=(name,label,type='text',extra={})=>({name,label,type,...extra});
const schemas={users:{label:'Users & roles',fields:[field('name','Name'),field('email','Email','email'),field('role','Role','select',{options:['Student','Teaching staff','Administrator','IT staff']}),field('department','Department'),field('status','Status','select',{options:['Active','Admitted','Graduated','Archived']})]},departments:{label:'Faculties & departments',fields:[field('name','Name'),field('faculty','Faculty'),field('head','Head'),field('status','Status','select',{options:['Active','Archived']})]},offerings:{label:'Courses & sections',fields:[field('code','Course code'),field('name','Name'),field('department','Department'),field('credits','Credits','number',{min:1,max:12,value:3}),field('prerequisite','Prerequisite','text',{optional:true}),field('section','Section'),field('capacity','Capacity','number',{min:1,max:1000,value:45}),field('enrolled','Enrolled count','number',{min:0,max:1000,value:0}),field('status','Status','select',{options:['Active','Archived']})]},calendar:{label:'Academic calendar',fields:[field('title','Title'),field('start','Start','date'),field('end','End','date'),field('status','Status','select',{options:['Draft','Published','Archived']})]},timetable:{label:'Timetable builder',fields:[field('course','Course','select',{options:courseOpts()}),field('teacher','Instructor'),field('date','Date','date'),field('start','Start','time'),field('end','End','time'),field('room','Room'),field('capacity','Room capacity','number',{min:1,max:2000,value:50}),field('seats','Class size','number',{min:1,max:2000,value:42}),field('status','Status','select',{options:['Draft','Published','Archived']})]},exams:{label:'Exams',fields:[field('title','Title'),field('course','Course','select',{options:courseOpts()}),field('date','Date','date'),field('start','Start','time'),field('end','End','time'),field('room','Room'),field('seat','Seat number'),field('release','Seat release date','date'),field('instructions','Instructions','textarea'),field('status','Status','select',{options:['Draft','Published','Archived']})]},questions:{label:'Question bank',fields:[field('title','Question','textarea'),field('course','Course','select',{options:courseOpts()}),field('type','Question type','select',{options:['Multiple choice','True / false','Matching','Essay','Problem-solving']}),field('options','Options (one per line); matching uses left = right','textarea',{optional:true}),field('answer','Correct option index (0 is first); not needed for written/matching','text',{optional:true}),field('topic','Topic'),field('difficulty','Difficulty','select',{options:['Easy','Medium','Hard']}),field('outcome','Learning outcome'),field('model','Model answer','textarea')]},materials:{label:'Course materials',fields:[field('title','Title'),field('course','Course','select',{options:courseOpts()}),field('folder','Folder'),field('release','Release date','date'),field('body','Study notes','textarea',{optional:true}),field('file','Attach file (up to 10 MB)','file',{optional:true}),field('status','Status','select',{options:['Draft','Published','Archived']})]},announcements:{label:'Announcements',fields:[field('title','Title'),field('body','Body','textarea'),field('target','Audience','select',{options:['All','Student','Teaching staff',...courses.map(c=>c.id)]}),field('effective','Effective date','date'),field('status','Status','select',{options:['Draft','Published','Archived']})]},lost:{label:'Lost & found',fields:[field('title','Title'),field('location','Location'),field('description','Description','textarea'),field('photo','Photo (up to 10 MB)','file',{optional:true,accept:'image/*'}),field('date','Date','date'),field('status','Status','select',{options:['Lost','Found','Returned']})]},incidents:{label:'Incidents & alerts',fields:[field('title','Title'),field('service','Affected service','select',{options:['Academic API','Assessment service','Database','Object storage','Network','Realtime','AI gateway']}),field('severity','Severity','select',{options:['Low','Medium','High','Critical']}),field('owner','Owner'),field('status','Status','select',{options:['Open','In progress','Escalated','Resolved']}),field('notes','Resolution / investigation notes','textarea')]},workflows:{label:'Workflow automation',fields:[field('name','Name'),field('trigger','Trigger','select',{options:['High-priority ticket','Unassigned ticket','Open incident']}),field('action','Action','select',{options:['Assign to IT support','Assign to Student services','Escalate open incidents']}),field('enabled','Enabled','checkbox')]}};
function formField(f,v){let value=v??f.value??'';let common=`name="${f.name}" id="field-${f.name}" ${f.optional?'':'required'} ${f.min!==undefined?`min="${f.min}"`:''} ${f.max!==undefined?`max="${f.max}"`:''}`;return `<label class="${f.type==='textarea'?'span2':''}">${tr(f.label)}${f.optional?'':' *'}${f.type==='textarea'?`<textarea ${common} maxlength="10000">${esc(value)}</textarea>`:f.type==='select'?`<select ${common}>${f.options.map(o=>{let [val,text]=Array.isArray(o)?o:[o,o];return `<option value="${esc(val)}" ${String(val)===String(value)?'selected':''}>${tr(text)}</option>`}).join('')}</select>`:f.type==='checkbox'?`<input type="checkbox" name="${f.name}" ${value?'checked':''} style="width:20px">`:`<input type="${f.type}" ${common} ${f.type==='file'?`accept="${f.accept||'*/*'}"`:`value="${esc(value)}"`} ${f.type==='text'?'maxlength="300"':''}>`}</label>`}
function openEditor(kind,id){const sc=schemas[kind],record=(db[kind]||[]).find(x=>x.id===id)||{};modal(`<h2>${tr(id?'Edit':'Create')} · ${tr(sc.label)}</h2><p class="hint">${tr('Local records only')}. Fields marked * are required.</p><form class="form" id="recordForm" data-kind="${kind}" data-id="${id||''}"><div class="formgrid">${sc.fields.map(f=>formField(f,record[f.name])).join('')}</div><div class="formerror" role="alert"></div><div class="recordactions"><button class="primary">${tr('Save changes')}</button><button type="button" class="secondary" data-dismiss>${tr('Cancel')}</button></div></form>`)}
function tableView(kind,columns,rows=db[kind],canEdit=true){let matching=rows.filter(r=>(listStatus==='All'||r.status===listStatus)&&JSON.stringify(r).toLowerCase().includes(listQuery.toLowerCase()));let total=Math.max(1,Math.ceil(matching.length/8));listPage=Math.min(listPage,total);let slice=matching.slice((listPage-1)*8,listPage*8);return `<div class="toolbar"><input id="tableSearch" value="${esc(listQuery)}" placeholder="${tr('Search records…')}" aria-label="Search records"><select id="tableStatus" aria-label="Filter by status">${['All',...new Set(rows.map(r=>r.status).filter(Boolean))].map(s=>`<option value="${s}" ${s===listStatus?'selected':''}>${tr(s)}</option>`).join('')}</select><button class="secondary" data-export="${kind}">${tr('Export CSV')}</button></div><div class="tablewrap"><table><thead><tr>${columns.map(([k,t])=>`<th><button data-sort="${kind}:${k}" aria-label="Sort by ${t}">${tr(t)} ↕</button></th>`).join('')}${canEdit?`<th>${tr('Actions')}</th>`:''}</tr></thead><tbody>${slice.map(r=>`<tr>${columns.map(([k])=>`<td>${k==='status'?statusBadge(r[k]):esc(r[k]??'—')}</td>`).join('')}${canEdit?`<td class="tableactions"><button class="secondary" data-edit="${kind}:${r.id}">${tr('Edit')}</button></td>`:''}</tr>`).join('')}</tbody></table>${!slice.length?`<div class="empty">${tr(rows.length?'No results match your search.':'No records yet.')}</div>`:''}</div><div class="pagination"><span>${matching.length} ${lang==='ar'?'سجل':'records'} · ${listPage} / ${total}</span><div><button class="secondary" data-pagination="-1" ${listPage===1?'disabled':''}>${tr('Back')}</button> <button class="secondary" data-pagination="1" ${listPage===total?'disabled':''}>${tr('Next')}</button></div></div>`}
for(const kind of ['users','departments','offerings','calendar','timetable','questions','workflows'])draw[kind]=()=>vhead(schemas[kind].label,'Local records only',`<div class="recordactions">${kind==='users'?'<button class="secondary" id="importUsers">'+tr('Import CSV')+'</button>':''}<button class="primary" data-create="${kind}">+ ${tr('Create')}</button></div>`)+(kind==='timetable'?'<div class="notice">Room, instructor and section overlaps are checked before saving. Class size must fit room capacity.</div>':kind==='users'?'<div class="notice">These are sample directory records. They do not create login accounts or grant real permissions.</div>':kind==='workflows'?'<div class="notice">Rules run only when you select Run preview and confirm. There is no background automation.</div>':'')+tableView(kind,schemas[kind].fields.filter(f=>!['textarea','file','checkbox'].includes(f.type)).slice(0,6).map(f=>[f.name,f.label]))+(kind==='workflows'?'<button class="primary" id="runRules">Run preview</button>':'');
let idbPromise;function filesDB(){if(!idbPromise)idbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('uniflow-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return idbPromise}async function putFile(f){if(!f||!f.size)return '';if(f.size>10*1024*1024)throw Error('File must be 10 MB or smaller.');const database=await filesDB(),id=uid();await new Promise((res,rej)=>{let tx=database.transaction('files','readwrite');tx.objectStore('files').put({name:f.name,type:f.type,blob:f},id);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});return id}async function fileRecord(id){let database=await filesDB();return new Promise((res,rej)=>{let r=database.transaction('files').objectStore('files').get(id);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}async function retrieveFile(id,preview=false){try{const f=await fileRecord(id);if(!f)throw Error('This file is not available on this browser.');const url=URL.createObjectURL(f.blob);if(preview&&f.type.startsWith('image/')){modal(`<h2>${esc(f.name)}</h2><img src="${url}" alt="${esc(f.name)}" style="width:100%;max-height:60vh;object-fit:contain">`);setTimeout(()=>URL.revokeObjectURL(url),60000)}else{const a=document.createElement('a');a.href=url;a.download=f.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}catch(e){toast(e.message)}}
function formError(form,message){let err=form.querySelector('.formerror');if(err){err.textContent=message;err.classList.add('visible');err.scrollIntoView({block:'nearest'})}else toast(message)}
function validateRecord(kind,r,old){if(r.end&&r.start&&r.end<=r.start)return 'End must be after start.';if(kind==='users'&&db.users.some(u=>u.id!==old?.id&&u.email.toLowerCase()===r.email.toLowerCase()))return 'This email already exists in the local directory.';if(kind==='offerings'&&Number(r.enrolled)>Number(r.capacity))return 'Enrolled students cannot exceed section capacity.';if(kind==='offerings'&&r.prerequisite===r.code)return 'A course cannot be its own prerequisite.';if(kind==='timetable'){if(+r.seats>+r.capacity)return 'Class size exceeds room capacity.';let clash=db.timetable.find(t=>t.id!==old?.id&&t.status!=='Archived'&&r.status!=='Archived'&&t.date===r.date&&r.start<t.end&&r.end>t.start&&(t.room.toLowerCase()===r.room.toLowerCase()||t.teacher.toLowerCase()===r.teacher.toLowerCase()||t.course===r.course));if(clash)return `Schedule conflict with ${clash.course}, ${clash.start}–${clash.end} in ${clash.room}. Choose another time, room or instructor.`}if(kind==='incidents'&&r.status==='Resolved'&&r.notes.trim().length<10)return 'Add meaningful resolution notes before resolving the incident.';if(kind==='questions'){if(['Multiple choice','True / false'].includes(r.type)){let opts=r.type==='True / false'?['True','False']:r.options.split('\n').filter(Boolean);if(opts.length<2||!/^\d+$/.test(r.answer)||+r.answer>=opts.length)return 'Add at least two options and a valid zero-based correct option index.';if(r.type==='True / false')r.options='True\nFalse'}if(r.type==='Matching'&&!r.options.split('\n').every(x=>x.includes('=')&&x.split('=').every(t=>t.trim())))return 'Use one matching pair per line: left = right.'}return ''}
function confirmAction(title,body,callback){modal(`<h2>${tr(title)}</h2><p class="explain">${esc(body)}</p><div class="recordactions"><button class="primary" id="confirmAction">${tr('Confirm')}</button><button class="secondary" data-dismiss>${tr('Cancel')}</button></div>`);$('#confirmAction').onclick=()=>{close();callback()}}
function visibleAnnouncements(context){return db.announcements.filter(n=>n.status==='Published'&&n.effective<=new Date().toISOString().slice(0,10)&&(['All',role,context].includes(n.target)))}
function materialsView(course){const teaching=role==='Teaching staff';const rows=db.materials.filter(m=>(!course||m.course===course)&&(teaching||(m.status==='Published'&&m.release<=nowISO().slice(0,10))));return `<div class="toolbar">${teaching?actionButton('Add material','data-create="materials"',true):''}<span class="hint">Files and notes are saved on this device. No server upload.</span></div><div class="recordgrid">${rows.map(m=>`<article class="record"><div class="recordtop"><span class="badge">${esc(m.course)} · v${m.version}</span>${statusBadge(m.status)}</div><h3>${esc(m.title)}</h3><small>${esc(m.folder)} · ${esc(m.release)}</small><div class="recordactions"><button class="secondary" data-material="${m.id}">${tr('Preview')}</button><button class="secondary" data-download-material="${m.id}">${tr('Download')}</button>${teaching?`<button class="textbutton" data-edit="materials:${m.id}">${tr('Edit')}</button>`:''}</div></article>`).join('')}</div>${!rows.length?`<div class="empty">${tr('No records yet.')}</div>`:''}`}
draw.materials=()=>vhead('Course materials','Organise, version and release learning resources.')+materialsView();
function assignmentsView(course){let list=state.tasks.filter(t=>!course||courses.find(c=>c.id===course)?.name===t.course);if(role==='Student')list=list.filter(t=>!t.status||t.status==='Published');list=list.filter(t=>(filter==='All'||filter==='Upcoming'&&!t.submitted&&!t.done||filter==='Submitted'&&t.submitted||filter==='Graded'&&t.grade!==undefined||filter==='Needs attention'&&!t.submitted&&Date.parse(t.due)<Date.now())&&(t.title+t.course).toLowerCase().includes(listQuery.toLowerCase()));return `<div class="toolbar">${['All','Upcoming','Submitted','Needs attention','Graded'].map(f=>`<button class="chip ${filter===f?'selected':''}" data-assignment-filter="${f}">${tr(f)}</button>`).join('')}</div>${list.map(t=>`<div class="taskrow"><div><h3>${esc(t.title)}</h3><small>${esc(t.course)} · ${esc(t.due)}${t.status?' · '+tr(t.status):''}</small></div>${statusBadge(t.submitted?'Submitted':t.done?'Completed':'Pending')}<button class="${t.submitted?'secondary':'primary'}" data-assignment="${t.id}">${tr(t.submitted?'View submission':'Open')}</button></div>`).join('')}${!list.length?`<div class="empty">${tr('No results match your search.')}</div>`:''}`}
draw.assignments=()=>vhead('Assignments','Instructions, deadlines and submissions in one place.',`<button class="primary" id="newAssignment">+ ${tr(role==='Teaching staff'?'Create assignment':'Add personal task')}</button>`)+assignmentsView();
function assignmentDetail(id){let t=state.tasks.find(t=>t.id==id);if(!t)return;modal(`<span class="badge">${esc(t.course)}</span><h2 style="margin-top:16px">${esc(t.title)}</h2><dl><div class="definition"><dt>Due</dt><dd>${esc(t.due)}</dd></div><div class="definition"><dt>${tr('Instructions')}</dt><dd>${esc(t.instructions||'Complete the exercise, explain your approach, and attach your work. This is a sample assignment.')}</dd></div><div class="definition"><dt>Late / resubmission policy</dt><dd>${esc(t.latePolicy||'Late work requires instructor review. One resubmission is allowed before the deadline.')}</dd></div></dl>${t.submitted?`<div class="notice"><b>Submission receipt ${esc(t.receipt||'LOCAL-'+t.id)}</b><br>${t.submittedAt?stamp(t.submittedAt):'Saved locally'} · ${t.sync||'Local submission — not sent to a server'}</div><p>${esc(t.answer||'')}</p>${t.fileId?`<button class="secondary" data-file="${t.fileId}">↓ ${esc(t.filename)}</button>`:''}${!t.resubmitted&&Date.parse(t.due)>Date.now()?`<button class="secondary" data-resubmit="${t.id}">Resubmit</button>`:''}`:`<form class="form" id="assignmentSubmit" data-id="${t.id}"><label>Your response<textarea name="answer" required maxlength="15000"></textarea></label><label>Attach your work (up to 10 MB)<input type="file" name="attachment"></label><div class="hint">File contents are saved in this browser. The original file is available for download after saving.</div><div class="formerror" role="alert"></div><label class="rowcheck"><input type="checkbox" required>I have checked my response and selected file.</label><button class="primary">${tr('Save demo submission')}</button></form>`}${role==='Teaching staff'?`<div class="recordactions"><button class="secondary" data-edit-assignment="${t.id}">${tr('Edit')}</button></div>`:''}${t.model&&t.modelRelease&&Date.parse(t.modelRelease)<=Date.now()?`<details><summary>Released model answer</summary><p>${esc(t.model)}</p></details>`:''}`)}
function newAssignment(id){let t=state.tasks.find(t=>t.id==id)||{};modal(`<h2>${tr(role==='Teaching staff'?'Create assignment':'Add personal task')}</h2><form class="form" id="assignmentEditor" data-id="${id||''}"><div class="formgrid">${[field('title','Title'),field('course','Course','select',{options:courses.map(c=>c.name)}),field('due','Deadline','datetime-local'),field('instructions','Instructions','textarea'),...(role==='Teaching staff'?[field('latePolicy','Late policy','textarea'),field('rubric','Rubric','textarea'),field('model','Model answer','textarea'),field('modelRelease','Model answer release','datetime-local'),field('status','Status','select',{options:['Draft','Published']})]:[])].map(f=>formField(f,t[f.name])).join('')}</div><div class="formerror" role="alert"></div><button class="primary">${tr('Save changes')}</button></form>`)}
function quizList(course){let qs=db.assessments.filter(q=>(!course||q.course===course)&&(role==='Teaching staff'||q.status==='Published'));return `<div class="toolbar">${role==='Teaching staff'?'<button class="primary" id="buildQuiz">+ '+tr('Create quiz')+'</button>':''}</div><div class="recordgrid">${qs.map(q=>{let attempts=db.attempts.filter(a=>a.quiz===q.id),active=attempts.find(a=>a.status==='In progress');return `<article class="record"><div class="recordtop"><span class="badge">${esc(q.course)}</span>${statusBadge(q.status)}</div><h3>${esc(q.title)}</h3><p>${q.duration} minutes · ${q.questions.length} questions · ${attempts.filter(a=>a.status!=='In progress').length}/${q.attempts} attempts used</p><small>Available ${esc(q.open)} — ${esc(q.close)}</small><div class="recordactions"><button class="primary" data-quiz="${q.id}">${tr(active?'Resume attempt':'Start quiz')}</button>${attempts.some(a=>a.status!=='In progress')?`<button class="secondary" data-results="${q.id}">${tr('View results')}</button>`:''}${role==='Teaching staff'?`<button class="secondary" data-edit-quiz="${q.id}">${tr('Edit')}</button>`:''}</div></article>`}).join('')}</div>${!qs.length?'<div class="empty">'+tr('No records yet.')+'</div>':''}`}
draw.quizzes=()=>vhead('Quizzes & exams','Practice, save your progress and review released feedback.')+quizList();
function quizBuilder(id){let q=db.assessments.find(q=>q.id===id)||{};modal(`<h2>${tr('Create quiz')}</h2><form class="form" id="quizBuilder" data-id="${id||''}"><div class="formgrid">${[field('title','Title'),field('course','Course','select',{options:courseOpts()}),field('duration','Duration (minutes)','number',{min:1,max:180,value:10}),field('attempts','Attempt limit','number',{min:1,max:10,value:2}),field('open','Open date','date'),field('close','Close date','date'),field('release','Results release','date'),field('status','Status','select',{options:['Draft','Published','Archived']}),field('instructions','Instructions','textarea')].map(f=>formField(f,q[f.name])).join('')}</div><fieldset><legend>Question bank</legend>${db.questions.map(x=>`<label class="rowcheck"><input type="checkbox" name="questionIds" value="${x.id}" ${q.questions?.includes(x.id)?'checked':''}>${esc(x.title)} · ${x.type}</label>`).join('')}</fieldset><label class="rowcheck"><input name="random" type="checkbox" ${q.random?'checked':''}>Randomise question order</label><div class="formerror" role="alert"></div><button class="primary">${tr('Save changes')}</button></form>`)}
function beginQuiz(id){const q=db.assessments.find(q=>q.id===id);let existing=db.attempts.find(a=>a.quiz===id&&a.status==='In progress');if(existing){activeAttempt=existing.id;quizIndex=0;go('attempt');return}let today=nowISO().slice(0,10);if(today<q.open||today>q.close){toast('This quiz is outside its availability window.');return}if(db.attempts.filter(a=>a.quiz===id).length>=q.attempts){showResults(id);return}modal(`<h2>${esc(q.title)}</h2><p>${esc(q.instructions)}</p><div class="notice">${q.duration} minutes · ${q.questions.length} questions · browser-local timer.<br>This practice timer is not a secure server-authoritative exam session.</div><form class="form" id="startQuiz" data-id="${id}"><label class="rowcheck"><input type="checkbox" required>I am ready. My timed attempt will begin.</label><button class="primary">${tr('Start quiz')}</button></form>`)}
function currentAttempt(){return db.attempts.find(a=>a.id===activeAttempt)||db.attempts.find(a=>a.status==='In progress')}
draw.attempt=()=>{let a=currentAttempt();if(!a)return `<div class="empty">No active attempt.<br><button class="primary" data-page="quizzes">${tr('Quizzes & exams')}</button></div>`;activeAttempt=a.id;let q=db.assessments.find(q=>q.id===a.quiz);if(a.status!=='In progress')return `<section class="panel"><h2>Attempt submitted</h2><p>${stamp(a.submitted)}</p><button class="primary" data-results="${q.id}">${tr('View results')}</button>${a.appeal?`<div class="notice" style="margin-top:15px">Appeal submitted · A teaching assistant was notified for manual review.</div>`:`<button class="secondary" style="margin-inline-start:8px" data-appeal="${a.id}">Appeal auto-correction</button>`}</section>`;let questions=a.questionSnapshots||a.order.map(id=>db.questions.find(x=>x.id===id));quizIndex=Math.min(quizIndex,questions.length-1);let item=questions[quizIndex],value=a.answers[item.id];let control;if(['Multiple choice','True / false'].includes(item.type))control=`<div class="quizoptions">${item.options.split('\n').filter(Boolean).map((o,i)=>`<label><input type="radio" name="quizAnswer" data-answer="${item.id}" value="${i}" ${String(value)===String(i)?'checked':''}>${esc(o)}</label>`).join('')}</div>`;else if(item.type==='Matching'){let pairs=item.options.split('\n').filter(Boolean).map(s=>s.split('=').map(s=>s.trim()));control=`<div class="form">${pairs.map(([l],i)=>`<label>${esc(l)}<select data-match="${item.id}" data-pair="${i}"><option value="">Choose a match</option>${pairs.map(([,r],j)=>`<option value="${j}" ${String(value?.[i])===String(j)?'selected':''}>${esc(r)}</option>`).reverse().join('')}</select></label>`).join('')}</div>`}else control=`<div class="form"><label>Your answer<textarea data-written="${item.id}" maxlength="15000">${esc(value||'')}</textarea></label>${item.type==='Problem-solving'?`<label>Handwritten work / supporting file<input type="file" data-quiz-file="${item.id}"></label><small>${esc(a.files?.[item.id]?.name||'Files stay on this browser.')}</small>`:''}</div>`;return vhead(q.title,`${q.course} · ${tr('Quiz attempt')}`)+`<div class="quizlayout"><section class="panel"><span class="badge">Question ${quizIndex+1} / ${questions.length} · ${esc(item.type)}</span><h2 style="margin:20px 0;line-height:1.7">${esc(item.title)}</h2>${control}<div class="quizfooter"><button class="secondary" data-question-step="-1" ${quizIndex===0?'disabled':''}>${tr('Back')}</button>${quizIndex<questions.length-1?'<button class="primary" data-question-step="1">'+tr('Next')+'</button>':'<button class="primary" id="finishQuiz">Review & submit</button>'}</div></section><aside><section class="panel"><div><small>Time remaining</small><div class="quiztimer" id="quizTimer">--:--</div></div><div class="questionnav">${questions.map((x,i)=>`<button data-question-index="${i}" aria-label="Question ${i+1}" class="${a.answers[x.id]!==undefined?'answered':''} ${i===quizIndex?'current':''}">${i+1}</button>`).join('')}</div><small id="autosave" role="status">Saved on this device</small><button class="textbutton" id="finishQuiz">Review & submit</button></section></aside></div>`};
function startTimer(){const tick=()=>{let a=currentAttempt();if(!a||a.status!=='In progress')return;let seconds=Math.max(0,Math.ceil((a.ends-Date.now())/1000));let timer=$('#quizTimer');if(timer)timer.textContent=`${Math.floor(seconds/60).toString().padStart(2,'0')}:${(seconds%60).toString().padStart(2,'0')}`;if(!seconds){clearInterval(quizTick);submitQuiz(a.id);}};tick();quizTick=setInterval(tick,1000)}
function submitQuiz(id){let a=db.attempts.find(a=>a.id===id);if(!a||a.status!=='In progress')return;let questions=a.questionSnapshots||a.order.map(q=>db.questions.find(x=>x.id===q));let auto=questions.filter(q=>!['Essay','Problem-solving'].includes(q.type));a.autoTotal=auto.length;a.autoScore=auto.filter(q=>q.type==='Matching'?q.options.split('\n').filter(Boolean).every((_,i)=>String(a.answers[q.id]?.[i])===String(i)):String(a.answers[q.id])===String(q.answer)).length;a.status=questions.length>auto.length?'Needs review':'Completed';a.submitted=nowISO();audit('Quiz submitted',`${a.quiz} · ${a.autoScore}/${a.autoTotal} auto-scored`);notify('Quiz submission saved','quizzes');persist();render();toast('Attempt saved. Written answers await instructor review.')}
function showResults(id){let q=db.assessments.find(q=>q.id===id);let attempts=db.attempts.filter(a=>a.quiz===id&&a.status!=='In progress');modal(`<h2>${esc(q.title)} · Results</h2>${!attempts.length?'<p>No completed attempts.</p>':attempts.map(a=>`<section class="panel"><b>${stamp(a.submitted)}</b><p>${tr(a.status)}</p>${a.appeal?'<div class="notice">Appeal submitted · manual review requested.</div>':`<button class="secondary" data-appeal="${a.id}">Appeal auto-correction</button>`}${nowISO().slice(0,10)>=q.release?`<h2>${a.autoScore} / ${a.autoTotal} auto-scored</h2><small>Written responses are excluded until instructor review.</small>${(a.questionSnapshots||a.order.map(id=>db.questions.find(x=>x.id===id))).map(item=>`<details style="margin-top:16px"><summary>${esc(item.title)}</summary><p>${esc(item.model)}</p>${a.files?.[item.id]?`<button class="secondary" data-file="${a.files[item.id].id}">Download attached work</button>`:''}</details>`).join('')}`:`<div class="notice">Results are available on ${esc(q.release)}.</div>`}</section>`).join('')}`)}
draw.exams=()=>vhead('Exams','Dates, rooms, instructions and seat allocation.',role==='Administrator'?`<button class="primary" data-create="exams">+ ${tr('Create')}</button>`:'')+`<div class="recordgrid">${db.exams.filter(e=>role==='Administrator'||e.status==='Published').map(e=>`<article class="record"><span class="badge">${esc(e.course)}</span><h3>${esc(e.title)}</h3><p>${esc(e.date)} · ${esc(e.start)}–${esc(e.end)}</p><b>${esc(e.room)}</b><div class="notice">${e.release<=nowISO().slice(0,10)?`Seat: ${esc(e.seat)}`:`Seat number available on ${esc(e.release)}`}</div><p>${esc(e.instructions)}</p>${role==='Administrator'?`<button class="secondary" data-edit="exams:${e.id}">${tr('Edit')}</button>`:''}</article>`).join('')}</div>`;
function attendanceView(course){let active=db.attendanceSessions.filter(s=>(!course||s.course===course)&&s.expires>Date.now());return `<div class="notice">Name-entry check-in is supported locally and stays pending until an instructor confirms. Secure rotating QR validation requires a server; it is not simulated as verified attendance.</div><div class="toolbar">${role==='Teaching staff'?'<button class="primary" id="startAttendance">+ '+tr('Start session')+'</button>':''}<button class="secondary" data-export="attendanceRequests">${tr('Export CSV')}</button><button class="secondary" id="attendanceCorrection">${tr('Request correction')}</button></div>${active.map(s=>`<section class="panel"><div class="sectionhead"><h2>${esc(s.course)} · ${esc(s.section)}</h2><span class="badge">Closes ${new Date(s.expires).toLocaleTimeString()}</span></div>${role==='Student'?`<button class="primary" data-checkin="${s.id}">${tr('Check in')}</button>`:`<p>Name-entry session active. Switch to the Student demo workspace to create a pending request.</p><button class="secondary" data-end-session="${s.id}">End session</button>`}</section>`).join('')}<div class="tablewrap"><table><thead><tr><th>${tr('Name')}</th><th>${tr('Course')}</th><th>${tr('Date')}</th><th>${tr('Status')}</th><th>${tr('Actions')}</th></tr></thead><tbody>${db.attendanceRequests.filter(r=>!course||r.course===course).map(r=>`<tr><td>${esc(r.name)}</td><td>${esc(r.course)}</td><td>${stamp(r.at)}</td><td>${statusBadge(r.status)}</td><td>${role==='Teaching staff'?`<button class="secondary" data-attendance="${r.id}:Present">${tr('Present')}</button><button class="secondary" data-attendance="${r.id}:Absent">${tr('Absent')}</button><button class="secondary" data-attendance="${r.id}:Late">${tr('Late')}</button>`:`Receipt ${r.id.slice(0,8)}`}</td></tr>`).join('')}</tbody></table>${!db.attendanceRequests.length?`<div class="empty">${tr('No records yet.')}${!active.length?'<br>No active check-in session.':' '}</div>`:''}</div>`}
draw.attendance=()=>vhead('Attendance','View sessions, submit a check-in and request a correction.')+attendanceView();
function announcementsView(course){let edit=['Teaching staff','Administrator'].includes(role),list=edit?db.announcements.filter(n=>!course||n.target===course||n.target==='All'):visibleAnnouncements(course);return `<div class="toolbar">${edit?'<button class="primary" data-create="announcements">+ '+tr('Create')+'</button>':''}</div>${list.map(n=>`<article class="panel"><div class="sectionhead"><h2>${esc(n.title)}</h2>${statusBadge(n.status)}</div><p style="white-space:pre-wrap">${esc(n.body)}</p><small>${esc(n.effective)} · Version ${n.version} · ${esc(n.target)}</small>${edit?`<button class="textbutton" data-edit="announcements:${n.id}">${tr('Edit')}</button>`:''}</article>`).join('')}${!list.length?'<div class="empty">'+tr('No records yet.')+'</div>':''}`}
draw.announcements=()=>vhead('Announcements','Published updates and dated institutional documents.')+announcementsView();
function makeRequest(kind='General',prefill=''){modal(`<h2>${tr('Create request')}</h2><form id="supportForm" class="form"><div class="formgrid">${[field('title','Title'),field('category','Category','select',{options:['General','Assignment','Grade review','Attendance correction','Lost & found','IT support','Complaint']}),field('detail','Description','textarea'),field('priority','Priority','select',{options:['Normal','High','Critical']})].map(f=>formField(f,f.name==='category'?kind:f.name==='title'?prefill:undefined)).join('')}</div><div class="formerror" role="alert"></div><button class="primary">${tr('Save on this device')}</button></form>`)}
draw.support=()=>{let staff=role!=='Student';return vhead('Support requests','A clear status and a next step for every request.',`<button class="primary" id="createRequest">+ ${tr('Create request')}</button>`)+`<div class="toolbar"><input id="tableSearch" aria-label="Search requests" placeholder="${tr('Search records…')}" value="${esc(listQuery)}"><select id="tableStatus" aria-label="Request status">${['All','Open','In progress','Needs information','Escalated','Resolved'].map(s=>`<option value="${s}" ${s===listStatus?'selected':''}>${tr(s)}</option>`).join('')}</select></div>${db.tickets.filter(t=>(listStatus==='All'||t.status===listStatus)&&JSON.stringify(t).toLowerCase().includes(listQuery.toLowerCase())).map(t=>`<div class="taskrow"><div><h3>${esc(t.title)}</h3><small>${t.reference} · ${esc(t.category)} · ${esc(t.owner)} · ${stamp(t.created)}</small></div>${statusBadge(t.status)}<button class="secondary" data-ticket="${t.id}">${tr('Open')}</button></div>`).join('')}${!db.tickets.length?'<div class="empty">'+tr('No records yet.')+'</div>':''}<small>Local requests are not transmitted to university staff.</small>`};
function ticketDetail(id){let t=db.tickets.find(t=>t.id===id),staff=role!=='Student';modal(`<span class="badge">${esc(t.reference)} · ${tr(t.priority)}</span><h2 style="margin-top:15px">${esc(t.title)}</h2><p>${esc(t.detail)}</p><small>Owner: ${esc(t.owner)} · Response target: ${stamp(t.sla)}</small><div class="pillline">${statusBadge(t.status)}</div>${t.history.filter(h=>staff||!h.internal).map(h=>`<div class="auditentry"><b>${esc(h.action)}</b><small>${stamp(h.at)} · ${esc(h.role)}</small><p>${esc(h.note)}</p></div>`).join('')}<form class="form" id="ticketUpdate" data-id="${id}">${staff?`${formField(field('status','Status','select',{options:['Open','In progress','Needs information','Escalated','Resolved']}),t.status)}${formField(field('owner','Owner'),t.owner)}`:''}<label>${staff?'Response / resolution notes':'Add a reply'}<textarea name="note" required maxlength="5000"></textarea></label>${staff?'<label class="rowcheck"><input type="checkbox" name="internal">Internal note (hidden in Student demo view)</label>':''}<button class="primary">${tr('Save changes')}</button></form>`)}
draw.enrolments=()=>vhead('Enrolments','Review registrations with prerequisite and capacity checks.',`<button class="primary" id="newEnrolment">+ ${tr('Create')}</button>`)+`<div class="tablewrap"><table><thead><tr><th>${tr('Name')}</th><th>${tr('Course')}</th><th>${tr('Prerequisite')}</th><th>${tr('Status')}</th><th>${tr('Actions')}</th></tr></thead><tbody>${db.enrolments.map(e=>`<tr><td>${esc(e.student)}</td><td>${esc(e.course)}</td><td>${e.prerequisite?'Met':'Missing'}</td><td>${statusBadge(e.status)}</td><td>${['Pending','Waitlisted'].includes(e.status)?`<button class="secondary" data-enrol="${e.id}:Approved">Approve</button><button class="secondary" data-enrol="${e.id}:Rejected">Reject</button>`:e.status==='Approved'?`<button class="secondary" data-enrol="${e.id}:Withdrawn">Withdraw</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`;
function messagesView(context=currentThread){currentThread=context;let channel=context.startsWith('Direct:')?'Private conversation':'Course channel';return `<div class="toolbar"><select id="threadSelect" aria-label="Conversation">${[...courses.map(c=>[c.id,c.name]),['Direct:Michael Tan','Direct: Dr. Michael Tan']].map(([k,n])=>`<option value="${k}" ${k===context?'selected':''}>${esc(n)}</option>`).join('')}</select><button class="secondary" id="muteChannel">${tr(db.mute?'Unmute':'Mute')}</button><button class="secondary" id="reportChannel">${tr('Report')}</button></div><section class="panel"><div class="sectionhead"><h2>${esc(channel)}</h2><span class="badge">${tr('Local demo')}</span></div><div class="messageslist" id="chatMessages"><div class="chatbubble"><b>Welcome to your ${channel.toLowerCase()}.</b><br>Messages stay in this browser. No other users receive them.</div>${db.chat.filter(m=>m.thread===context).map(m=>`<div class="chatbubble mine"><b>${esc(m.author)}</b><br>${esc(m.body)}<small style="color:#fffacd">${stamp(m.at)}</small></div>`).join('')}</div><form class="chatinput" id="chatComposer"><input name="body" required maxlength="3000" aria-label="Message" placeholder="${tr('New message')}"><button class="primary">${tr('Send')}</button></form></section>`}
draw.messages=()=>vhead('Messages','Course channels and private conversation previews.')+messagesView();
draw.appointments=()=>vhead('Appointments','Choose an available office-hour slot.',`<button class="primary" id="bookOfficeV2">+ ${tr('Book appointment')}</button>`)+`<section class="panel">${db.appointments?.length?db.appointments.map(a=>`<div class="healthrow"><div><b>${esc(a.teacher)}</b><small>${esc(a.slot)} · ${esc(a.reason)}</small></div><button class="secondary" data-cancel-booking="${a.id}">${tr('Cancel')}</button></div>`).join(''):'<div class="empty">No appointments booked yet.</div>'}<small>Local booking only. Staff calendars are not connected.</small></section>`;
draw.schedule=()=>{const sessions=db.timetable.filter(t=>t.status==='Published'&&(!listQuery||t.course===listQuery)).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));const minutes=t=>{const [sh,sm]=t.start.split(':').map(Number),[eh,em]=t.end.split(':').map(Number);return `${Math.max(0,(eh*60+em)-(sh*60+sm))} min`};return vhead('Schedule','Your weekly classes and academic dates.',`<button class="secondary" id="exportAllCalendar">↓ Export iCalendar</button>`)+`<div class="toolbar"><select id="scheduleCourse" aria-label="Filter schedule by course"><option value="">All courses</option>${courseOpts().map(([v,t])=>`<option value="${v}" ${listQuery===v?'selected':''}>${esc(t)}</option>`).join('')}</select><button class="secondary" data-page="exams">${tr('Exams')}</button><button class="secondary" data-page="appointments">${tr('Appointments')}</button></div><div class="schedule-layout"><section class="panel schedule-summary"><h2>Weekly overview</h2><p>Published course sessions for your timetable.</p><div class="schedule-count">${sessions.length}<small>scheduled class${sessions.length===1?'':'es'}</small></div><button class="secondary" data-page="appointments">Book office hours</button><h3>Academic calendar</h3>${db.calendar.filter(c=>c.status==='Published').map(c=>`<div class="healthrow"><b>${esc(c.title)}</b><small>${esc(c.start)} — ${esc(c.end)}</small></div>`).join('')||'<small>No upcoming academic dates.</small>'}</section><section class="panel timetable-panel"><div class="sectionhead"><div><h2>Class timetable</h2><small>Course, hall, duration and lecturer</small></div></div>${sessions.map(t=>`<article class="timetable-row"><span class="badge">${esc(t.date)}</span><h3>${esc(courses.find(c=>c.id===t.course)?.name||t.course)}</h3><dl><div><dt>Hall / room</dt><dd><button class="textbutton" data-building="Engineering">${esc(t.room)} ↗</button></dd></div><div><dt>Duration</dt><dd>${minutes(t)} · ${esc(t.start)}–${esc(t.end)}</dd></div><div><dt>Lecturer</dt><dd>${esc(t.teacher)}</dd></div></dl></article>`).join('')||'<div class="empty">No published classes match this filter.</div>'}</section></div>`};
const buildings=[['Library','North wing','08:00–22:00'],['Engineering','Central campus','Rooms 101–315'],['Science','East wing','Rooms 120–220'],['Student services','Main building','09:00–17:00'],['Health centre','East wing','09:00–17:00'],['Sports centre','South wing','07:00–21:00']];draw.map=()=>vhead('Campus map','Illustrative campus directory — not a live navigation map.')+`<div class="toolbar"><input id="buildingSearch" aria-label="Search campus buildings" placeholder="${tr('Search records…')}" value="${esc(listQuery)}"></div><div class="campusmap" id="mapBuildings">${buildings.filter(b=>b.join(' ').toLowerCase().includes(listQuery.toLowerCase())).map(b=>`<button class="building ${currentBuilding===b[0]?'selected':''}" data-building-select="${b[0]}">${icon('map')}<b>${esc(b[0])}</b><small>${esc(b[1])}</small></button>`).join('')}</div><section class="panel" style="margin-top:20px"><h2>${esc(currentBuilding)}</h2><p>${esc(buildings.find(b=>b[0]===currentBuilding)?.slice(1).join(' · ')||'')}</p><small>Ask the campus team for accessible routes and current access information.</small><button class="textbutton" data-page="support">${tr('Support requests')} →</button></section>`;
draw.lost=()=>vhead('Lost & found','Post an item and track its return.',`<button class="primary" data-create="lost">+ ${tr('Add item')}</button>`)+`<div class="recordgrid">${db.lost.map(x=>`<article class="record"><div class="recordtop">${statusBadge(x.status)}<small>${esc(x.date)}</small></div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><small>${esc(x.location)}</small><div class="recordactions">${x.photoId?`<button class="secondary" data-photo="${x.photoId}">Photo</button>`:''}<button class="secondary" data-edit="lost:${x.id}">${tr('Edit')}</button><button class="primary" data-contact-item="${x.id}">Contact via request</button></div></article>`).join('')}</div>`;
draw.campus=()=>vhead('Campus services','Find a place, join an event, or get help.')+`<div class="quickactions">${quick('map')}${quick('lost')}${quick('announcements')}${quick('support')}</div><h2 style="margin:24px 0">Campus events</h2><div class="recordgrid">${[['Innovation Week','2026-11-04','Workshops and student project showcases.'],['Design for Good','2026-11-06','A workshop on inclusive digital experiences.'],['Campus Run Club','2026-11-08','Meet at the main gate for a friendly morning run.']].map((e,i)=>`<article class="record"><span class="badge">${e[1]}</span><h3>${e[0]}</h3><p>${e[2]}</p><button class="primary" data-local-event="${i}">${state.joined.includes(i)?'Registered · cancel':'Register locally'}</button></article>`).join('')}</div>`;
draw.profile=()=>vhead('Profile & preferences','Manage your personal details and notification choices.')+`<div class="twocol"><section class="panel"><div class="profileinitials">${esc(db.profile.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</div><form class="form" id="profileForm"><label>${tr('Display name')}<input name="name" required maxlength="100" value="${esc(db.profile.name)}"></label><label>Phone number<input name="phone" type="tel" maxlength="30" value="${esc(db.profile.phone||'')}" placeholder="Add a phone number"></label><label class="dimmed-field">Email<input type="email" value="${esc(db.profile.email)}" disabled></label><label class="dimmed-field">Programme<input value="${esc(db.profile.programme)}" disabled></label><label class="dimmed-field">Academic year<input value="${esc(db.profile.year)}" disabled></label><small>Contact your university to update academic record details.</small><button class="primary">${tr('Save profile')}</button></form></section><section class="panel"><h2>${tr('Notification preferences')}</h2><form class="form" id="preferencesForm"><label class="rowcheck"><input type="checkbox" name="quizzes" ${db.prefs.quizzes!==false?'checked':''}>Quizzes</label><label class="rowcheck"><input type="checkbox" name="assignments" ${db.prefs.assignments!==false?'checked':''}>Assignments</label><small>Choose which assessment updates appear in your notifications.</small><label class="rowcheck"><input type="checkbox" name="email" ${db.prefs.email?'checked':''}>Email preference (delivery not connected)</label><label class="rowcheck"><input type="checkbox" name="push" ${db.prefs.push?'checked':''}>Push preference (delivery not connected)</label><label>${tr('Quiet hours start')}<input type="time" name="quiet" value="${db.prefs.quiet}"></label><label class="rowcheck"><input type="checkbox" name="motion" ${db.prefs.motion?'checked':''}>${tr('Reduce motion')}</label><button class="primary">${tr('Save changes')}</button></form><h2 style="margin-top:28px">${tr('Privacy')}</h2><p class="explain">Only sample information should be used. Data stays in this browser; role previews do not secure it from other people using this device.</p><button class="secondary" id="exportData">${tr('Export my demo data')}</button><button class="textbutton" data-page="capabilities">${tr('Feature status')} →</button></section></div>`;
draw.notifications=()=>vhead('Notifications','Updates with a clear next action.',`<button class="secondary" id="markNotifications">${tr('Mark all as read')}</button>`)+`<div class="toolbar">${['All','Unread'].map(s=>`<button class="chip ${listStatus===s?'selected':''}" data-notification-filter="${s}">${tr(s)}</button>`).join('')}<button class="secondary" data-page="profile">${tr('Notification preferences')}</button></div>${db.notifications.filter(n=>listStatus!=='Unread'||!n.read).map(n=>`<article class="notificationitem ${n.read?'read':''}">${icon(n.severity==='Critical'?'shield':'bell')}<div><h3>${esc(n.title)}</h3><small>${stamp(n.at)} · ${tr(n.severity)} · ${tr(n.read?'Read':'Unread')}</small></div><button class="secondary" data-notification="${n.id}">${tr('Open')}</button></article>`).join('')}${!db.notifications.length?'<div class="empty">No notifications yet. Activity in your demo workspace will appear here.</div>':''}`;
draw.grading=()=>vhead('Gradebook','Review first. Publish only after an explicit confirmation.',`<button class="secondary" data-export="grades">${tr('Export CSV')}</button>`)+`<div class="tablewrap"><table><thead><tr><th>${tr('Name')}</th><th>Assessment</th><th>Score</th><th>${tr('Status')}</th><th>${tr('Actions')}</th></tr></thead><tbody>${db.grades.map(g=>`<tr><td>${esc(g.student)}<small>${esc(g.course)}</small></td><td>${esc(g.assessment)}</td><td>${g.score}%</td><td>${statusBadge(g.status)}</td><td><button class="secondary" data-grade="${g.id}">${tr('Review')}</button>${g.status==='Approved'?`<button class="primary" data-publish-grade="${g.id}">${tr('Publish')}</button>`:''}</td></tr>`).join('')}</tbody></table></div><section class="panel" style="margin-top:22px"><h2>Quiz responses & appeals</h2>${db.attempts.filter(a=>a.status==='Needs review'||(a.appeal&&!a.appeal.reviewed)).map(a=>`<div class="healthrow"><div><b>${esc(db.assessments.find(q=>q.id===a.quiz)?.title)}</b><small>${a.appeal&&!a.appeal.reviewed?'Appeal · ':''}${stamp(a.submitted)}</small></div><button class="secondary" data-review-attempt="${a.id}">${tr('Review')}</button></div>`).join('')||'<div class="empty">No quiz responses or appeals awaiting review.</div>'}</section>`;
function reviewGrade(id){let g=db.grades.find(g=>g.id===id);modal(`<h2>${esc(g.assessment)}</h2><div class="pillline">${statusBadge(g.status)}${g.ai?'<span class="badge">AI-assisted example · not a model-generated score</span>':''}</div><dl><div class="definition"><dt>Rubric</dt><dd>${esc(g.rubric)}</dd></div><div class="definition"><dt>Sample answer evidence</dt><dd>${esc(g.quote)}</dd></div></dl><div class="notice">Example confidence: needs review. Verify correctness, edge cases and explanation before approving.</div><form class="form" id="reviewGradeForm" data-id="${id}">${formField(field('score','Score / 100','number',{min:0,max:100}),g.score)}${formField(field('feedback','Feedback','textarea'),g.feedback)}${formField(field('reason','Change reason','textarea'),'')}<label>Review decision<select name="status"><option>Draft</option><option>Approved</option><option>Rejected</option></select></label><div class="formerror" role="alert"></div><button class="primary">Save review (does not publish)</button></form>`)}
draw.students=()=>vhead('Students & groups','Sample roster and supportive follow-up.')+tableView('users',[['name','Name'],['email','Email'],['department','Department'],['status','Status']],db.users.filter(u=>u.role==='Student'),false)+`<section class="panel"><h2>Supportive follow-up</h2><p class="explain">Example signal: recursion mastery is 54% across 42 quiz responses. This is an aggregate teaching signal, not an individual risk prediction.</p><button class="secondary" data-page="messages">Open communication</button></section>`;
draw.analytics=()=>vhead('Analytics','Sample data with context, sample sizes and clear limitations.')+`<div class="notice">Illustrative metrics only. No predictive model or university data connection is active.</div><div class="twocol"><section class="panel"><h2>Topic understanding</h2><div class="heatmap"><div>Topic</div><div>Section A</div><div>B</div><div>C</div><div>n</div>${[['Arrays',92,89,90,42],['Trees',68,72,65,42],['Recursion',54,61,59,42],['Complexity',79,77,82,42]].map(row=>row.map((v,i)=>`<div class="${i?'cell '+(+v<65?'low':''):''}">${v}${i&&i<4?'%':''}</div>`).join('')).join('')}</div><p class="hint">Definition: share of correct tagged quiz answers. These are fixed sample values, not live student scores.</p></section><section class="panel"><h2>Common misconceptions</h2><div class="healthrow"><div><b>Recursion base cases</b><small>18 / 42 sample responses need review.</small></div></div><div class="healthrow"><div><b>Balanced versus skewed trees</b><small>13 / 42 sample responses need review.</small></div></div><p class="explain">Next step: revisit a small worked example and offer practice. Private assistant conversations are not shown.</p></section></div>`;
draw.finance=()=>vhead('Finance & budgets','Read-only illustration. No finance system is connected.')+`<div class="stats">${stat('$100','Configured AI budget','')}${stat('$12.40','Sample usage','')}${stat('$87.60','Sample remaining','')}${stat('12.4%','Sample utilisation','')}</div><section class="panel"><h2>Monthly budget illustration</h2><div class="tablewrap"><table><thead><tr><th>Category</th><th>Budget</th><th>Sample usage</th></tr></thead><tbody><tr><td>Study assistant</td><td>$60</td><td>$8.20</td></tr><tr><td>Teaching drafts</td><td>$30</td><td>$3.10</td></tr><tr><td>Administrative insights</td><td>$10</td><td>$1.10</td></tr></tbody></table></div><small>No fees, payments or financial transactions can be performed here.</small></section>`;
