const services=[['Academic API','Healthy','142 ms','0.02%'],['Assessment service','Healthy','98 ms','0.01%'],['Database','Healthy','24 ms','0.00%'],['Object storage','Healthy','34 ms','0.01%'],['Network','Healthy','18 ms','0.00%'],['Realtime','Healthy','41 ms','0.02%'],['AI gateway','Degraded','4,800 ms','2.8%']];
draw.operations=()=>vhead('Service health','Illustrative telemetry — no infrastructure connection.')+`<div class="notice">Sample incident: the AI gateway exceeds the 3-second p95 threshold. Open the incident to review evidence and record a response.</div><div class="tablewrap"><table><thead><tr><th>Service</th><th>Status</th><th>p95 latency</th><th>Error rate</th><th>Action</th></tr></thead><tbody>${services.map(s=>`<tr><td>${s[0]}</td><td>${statusBadge(s[1])}</td><td>${s[2]}</td><td>${s[3]}</td><td><button class="secondary" data-service="${s[0]}">Inspect</button></td></tr>`).join('')}</tbody></table></div>`;
draw.incidents=()=>vhead('Incidents & alerts','Assign an owner, record actions and resolve with notes.',`<button class="primary" data-create="incidents">+ ${tr('Create')}</button>`)+`<div class="recordgrid">${db.incidents.map(i=>`<article class="record"><div class="recordtop">${statusBadge(i.severity)}${statusBadge(i.status)}</div><h3>${esc(i.title)}</h3><p>${esc(i.service)} · ${esc(i.owner)}</p><small>${stamp(i.started||nowISO())}</small><div class="recordactions"><button class="primary" data-incident="${i.id}">${tr('Open')}</button></div></article>`).join('')}</div>`;
function incidentDetail(id){let i=db.incidents.find(x=>x.id===id);modal(`<h2>${esc(i.title)}</h2><div class="pillline">${statusBadge(i.status)}${statusBadge(i.severity)}</div><dl><div class="definition"><dt>Service / owner</dt><dd>${esc(i.service)} / ${esc(i.owner)}</dd></div><div class="definition"><dt>Sample telemetry evidence</dt><dd>Trace DEMO-1042 · p95 4,800 ms · errors 2.8% · threshold 3,000 ms.</dd></div></dl><p>${esc(i.notes)}</p>${(i.history||[]).map(h=>`<div class="auditentry"><b>${esc(h.status)}</b><small>${stamp(h.at)}</small><p>${esc(h.notes)}</p></div>`).join('')}<button class="primary" data-edit="incidents:${i.id}">Assign / update / resolve</button><button class="secondary" data-go-close="logs">View sample logs</button>`)}
draw.logs=()=>vhead('Logs & traces','Sample log entries — no live system access.')+`<div class="toolbar"><input id="logSearch" aria-label="Search sample logs" placeholder="Search service, trace or severity…" value="${esc(listQuery)}"></div><div class="tablewrap"><table><thead><tr><th>Time</th><th>Level</th><th>Service</th><th>Trace</th><th>Message</th></tr></thead><tbody>${[['08:00:00','WARN','AI gateway','DEMO-1042','Latency 4,800 ms exceeds 3,000 ms threshold'],['08:00:01','INFO','Academic API','DEMO-1043','Read completed in 142 ms'],['08:00:02','INFO','Database','DEMO-1044','Connection pool utilisation 42%'],['08:00:03','ERROR','AI gateway','DEMO-1045','Sample provider timeout']].filter(r=>r.join(' ').toLowerCase().includes(listQuery.toLowerCase())).map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
draw.storage=()=>vhead('Database & storage','Infrastructure example and this browser’s local file store.')+`<div class="stats">${stat('42%','Sample DB utilisation','')}${stat('12 GB','Sample database size','')}${stat('210 GB','Sample object storage','')}${stat('24 ms','Sample DB latency','')}</div><section class="panel"><h2>Files on this device</h2><p>Materials, assignment attachments and lost-item photos use IndexedDB. They are not backed up to a server and are available only on this browser.</p><button class="secondary" id="storageUsage">Check browser storage usage</button><p id="storageResult" role="status"></p></section>`;
