draw.settings=()=>vhead('AI governance','Local preference preview. No provider policy changes are sent.')+`<section class="panel"><form id="aiSettingsForm" class="form"><div class="formgrid">${[field('provider','Provider','select',{options:['Not connected','Hosted provider (planned)','Local model (planned)']}),field('region','Region','select',{options:['Not configured','Egypt (planned)','EU (planned)']}),field('budget','Monthly budget (USD)','number',{min:0,max:100000}),field('quota','Daily request quota','number',{min:0,max:10000})].map(f=>formField(f,db.ai[f.name])).join('')}</div>${[['study','Student study assistant'],['teaching','Teaching drafts'],['grading','AI-assisted grading'],['predictions','Advisory risk signals']].map(([k,v])=>`<label class="rowcheck"><input type="checkbox" name="${k}" ${db.ai[k]?'checked':''}>${v}</label>`).join('')}<label>Scope<select name="scope"><option>All demo roles and courses</option>${courses.map(c=>`<option>${c.id}</option>`).join('')}</select></label><div class="notice">These settings document a proposed configuration. They do not connect a provider, enforce quotas, or enable predictive decisions.</div><button class="primary">Review configuration</button></form></section>`;
draw.capabilities=()=>vhead('Feature status','What you can use now, and what needs a real university connection.')+`<section class="panel"><h2>Working on this device</h2>${['Course tabs, downloadable notes and local attachments','Assignments, submissions, receipts and one resubmission','Timed quizzes, autosave, question types and reviewable results','Attendance sessions, pending check-ins and instructor confirmation','Appointments, messages, event registrations and lost items','User directory, CSV import, academic structure and calendar','Timetable conflict checks, capacity and prerequisite validation','Grade review, approval and explicit publication','Requests, owner assignment, replies, resolution and history','Incident investigation, resolution notes and local audit','Notification centre, preferences, search and data export','Milano Red / Lemon Chiffon theme, mobile layout and Arabic navigation'].map(x=>`<div class="capability"><span>${x}</span><span class="badge">Local</span></div>`).join('')}</section><section class="panel"><h2>Requires backend / external connection</h2>${['University SSO, password recovery, MFA and real account provisioning','Server-enforced roles, tenant isolation, privacy controls and immutable audit','Live AI models, RAG over approved documents and predictive analytics','Cross-device records, real-time messages, push and email delivery','Secure rotating QR check-in and server-authoritative examinations','Server file storage, synchronisation and offline conflict resolution','Finance systems, campus geolocation and real monitoring / logs','Scheduled background automation and production backups'].map(x=>`<div class="capability"><span>${x}</span><span class="badge orange">Not connected</span></div>`).join('')}</section>`;
let assistantContext='CS201';draw.assistant=()=>vhead('AI assistant','Ask about the local sample records or study a prepared example.')+`<div class="chat"><div class="notice">${lang==='ar'?'المساعد الحالي يعمل بإجابات وقواعد تجريبية، وليس نموذج ذكاء اصطناعي متصل.':'Demo assistant: prepared explanations and local record lookups. No live AI model or institutional retrieval service is connected.'}</div><div class="toolbar"><select id="assistantContext" aria-label="Course context">${courseOpts().map(([k,v])=>`<option value="${k}" ${assistantContext===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="toolbar">${(role==='Teaching staff'?['Draft a lecture outline','Explain weak topics','What is the submission policy?']:['What is my GPA?','What is due next?','Explain binary search','What is the submission policy?']).map(q=>`<button class="chip" data-local-ask="${q}">${q}</button>`).join('')}</div><div id="assistantHistory">${db.assistant.map(m=>`<div class="chatbubble ${m.who==='user'?'mine':''}">${esc(m.text)}${m.source?`<div class="source">${esc(m.source)}${m.sourceId?` <button class="textbutton" data-source="${m.sourceId}">Inspect source ↗</button>`:''}</div><div class="recordactions"><button class="secondary" data-feedback="${m.id}:Helpful">Helpful</button><button class="secondary" data-feedback="${m.id}:Not helpful">Not helpful</button></div>`:''}</div>`).join('')}</div><form class="chatinput" id="assistantComposer"><input name="question" required maxlength="1500" aria-label="Ask assistant" placeholder="Ask about a course or deadline…"><button class="primary">${tr('Send')}</button></form></div>`;
function localAnswer(q){let text,source='Source: synthetic academic sample records',sourceId='';let s=q.toLowerCase();if(/gpa|grade|معدل|درجات/.test(s))text=lang==='ar'?'المعدل الحالي التجريبي 3.68 والتراكمي 3.61. استخدم حاسبة الدرجات لتجربة سيناريوهات؛ التقديرات لا تغيّر السجل.':'Your sample GPA is 3.68 and CGPA is 3.61. Use Grades & progress for published grades and a separate what-if estimate.';else if(/due|deadline|موعد|تكليف/.test(s)){text=state.tasks.filter(t=>!t.submitted&&!t.done).map(t=>`${t.title} — ${t.due}`).join('\n')||'No outstanding local tasks.';source='Source: assignments saved in this browser'}else if(/policy|submission|سياس/.test(s)){const n=db.announcements.find(n=>n.title.toLowerCase().includes('policy')&&n.status==='Published'&&n.effective<=nowISO().slice(0,10));if(n){text=n.body;source=`Source: ${n.title} · effective ${n.effective} · v${n.version}`;sourceId=n.id}else text='There is no published policy available in this sample workspace. Contact student services.'}else if(/binary|tree|شجر|بحث/.test(s)){text='Hint: start with a sorted list and compare the target with the middle value. Which half can you discard?\n\nFor [2, 5, 8, 12, 16, 23, 38] and target 23, compare with 12 and search the right half. Repeating this takes O(log n) comparisons.\n\nTry explaining why the list must be sorted.';source='Source: prepared CS201 study example';sourceId='m1'}else if(/outline|draft|lecture/.test(s)&&role==='Teaching staff'){text='Prepared draft — instructor review required.\n1. Define a binary search tree.\n2. Insert 8, 3, 10, 1, 6 on the board.\n3. Compare balanced and skewed search.\n4. Practice tracing an insertion.\n5. Exit question: explain the worst case.\n\nThis is a template, not live AI-generated content. Save it as a course material and review before publishing.';source='Source: prepared CS201 lesson template';sourceId='m1'}else if(/weak|recursion/.test(s)){text='In the sample analytics, recursion has 54% correct answers from 42 responses. Revisit base cases and trace a short function together. This is an aggregate example, not a student risk prediction.';source='Source: sample topic-mastery table'}else{text='I do not have enough connected information to answer that. Try GPA, deadlines, binary search or the sample submission policy. For an unresolved question, open Support requests.';source='No verified source available'}db.assistant.push({id:uid(),who:'user',text:q},{id:uid(),who:'assistant',text,source,sourceId});db.assistant=db.assistant.slice(-60);persist();render();$('#assistantHistory').lastElementChild?.scrollIntoView({block:'nearest',behavior:'smooth'})}
function exportCSV(kind){let records=db[kind]||[];if(!records.length){toast('No records to export.');return}let keys=Object.keys(records[0]).filter(k=>typeof records[0][k]!=='object');const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download(`uniflow-${kind}.csv`,'\uFEFF'+keys.map(cell).join(',')+'\r\n'+records.map(r=>keys.map(k=>cell(r[k])).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function parseCSV(text){const rows=[];let row=[],v='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){v+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(v);if(row.some(v=>v.trim()))rows.push(row);row=[];v=''}else v+=c}row.push(v);if(row.some(v=>v.trim()))rows.push(row);if(quoted)throw Error('CSV contains an unclosed quoted field.');return rows}
